/* Modern Minimal Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="modern-minimal-light"] {
  --background: hsl(300 50% 100%);
  --foreground: hsl(0 0% 19.89%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(0 0% 19.89%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(0 0% 19.89%);
  --primary: hsl(217.19 91.36% 59.41%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(300 0% 96.06%);
  --secondary-foreground: hsl(214.99 15.5% 34.68%);
  --muted: hsl(300 0% 97.37%);
  --muted-foreground: hsl(219.97 7.71% 45.75%);
  --accent: hsl(203.98 99.97% 93.54%);
  --accent-foreground: hsl(224.53 64.95% 33.15%);
  --destructive: hsl(359.91 86.11% 60.55%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(220.01 24.1% 91.61%);
  --input: hsl(220.01 24.1% 91.61%);
  --ring: hsl(217.19 91.36% 59.41%);
  --chart-1: hsl(217.19 91.36% 59.41%);
  --chart-2: hsl(221.24 86.4% 53.91%);
  --chart-3: hsl(224.36 76.88% 48.37%);
  --chart-4: hsl(225.99 71.15% 39.65%);
  --chart-5: hsl(224.53 64.95% 33.15%);
  --radius: 0.375rem;
  --sidebar: hsl(300 0% 97.37%);
  --sidebar-foreground: hsl(0 0% 19.89%);
  --sidebar-primary: hsl(217.19 91.36% 59.41%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(203.98 99.97% 93.54%);
  --sidebar-accent-foreground: hsl(224.53 64.95% 33.15%);
  --sidebar-border: hsl(220.01 24.1% 91.61%);
  --sidebar-ring: hsl(217.19 91.36% 59.41%);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow: 0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0 1px 3px 0px hsl(0 0% 0% / 0.1), 0 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

